input.command:
cd /tmp/verify && rm -f received.tgz
# Extract embedded base64 attachment from the packument and verify
curl -sS "http://registry.acme-internal.io/@acme%2fsdk-js" -o packument.json
node -e '
const fs=require("fs"),c=require("crypto");
const p=JSON.parse(fs.readFileSync("packument.json","utf8"));
const att=p._attachments["@acme/sdk-js-2.3.0.tgz"];
const buf=Buffer.from(att.data,"base64");
fs.writeFileSync("received.tgz",buf);
console.log("attachment declared length:",att.length,"actual bytes:",buf.length);
console.log("received shasum (sha1):",c.createHash("sha1").update(buf).digest("hex"));
console.log("received integrity     :","sha512-"+c.createHash("sha512").update(buf).digest("base64"));
const dist=p.versions["2.3.0"].dist;
console.log("published shasum       :",dist.shasum);
console.log("published integrity    :",dist.integrity);
'
